import argparse
from dataclasses import dataclass
from pathlib import Path
import math
import re

import numpy as np
from sklearn.feature_extraction.text import TfidfVectorizer

RECAPS_FOLDER = Path(__file__).parent / "recaps"

TOKEN_PATTERN = re.compile(r"[a-z0-9]+")


def tokenize(text: str) -> list[str]:
    """
    Basic tokenizer.

    This lowercases the text and keeps alphanumeric tokens.
    Markdown punctuation, table separators, and formatting markers
    are ignored naturally.
    """
    return TOKEN_PATTERN.findall(text.lower())


@dataclass
class Document:
    path: Path
    text: str
    tokens: list[str]

    @property
    def title(self) -> str:
        """
        Use the first Markdown heading as the display title.
        """
        for line in self.text.splitlines():
            if line.startswith("# "):
                return line[2:].strip()

        return self.path.stem


class RecapSearchEngine:
    def __init__(self, folder: str):
        self.folder = Path(folder)
        self.documents = self._load_documents()

        if not self.documents:
            raise ValueError(f"No Markdown files found in {self.folder}")

        self._build_tfidf_index()
        self._build_bm25_index()

    def _load_documents(self) -> list[Document]:
        documents = []

        for path in sorted(self.folder.rglob("*.md")):
            if not path.is_file():
                continue

            text = path.read_text(encoding="utf-8")
            tokens = tokenize(text)

            documents.append(
                Document(
                    path=path,
                    text=text,
                    tokens=tokens,
                )
            )

        return documents

    # ------------------------------------------------------------
    # TF-IDF
    # ------------------------------------------------------------

    def _build_tfidf_index(self):
        self.tfidf_vectorizer = TfidfVectorizer(
            tokenizer=tokenize,
            preprocessor=None,
            token_pattern=None,
            lowercase=False,
        )

        self.tfidf_matrix = self.tfidf_vectorizer.fit_transform(
            document.text for document in self.documents
        )

    def _search_tfidf(self, query: str, top_k: int):
        query_vector = self.tfidf_vectorizer.transform([query])

        # TfidfVectorizer normalizes vectors by default, so the dot
        # product is equivalent to cosine similarity.
        scores = self.tfidf_matrix @ query_vector.T
        scores = scores.toarray().ravel()

        ranked_indices = np.argsort(scores)[::-1]

        results = []

        for index in ranked_indices[:top_k]:
            if scores[index] <= 0:
                continue

            results.append(
                {
                    "document": self.documents[index],
                    "score": float(scores[index]),
                }
            )

        return results

    # ------------------------------------------------------------
    # BM25
    # ------------------------------------------------------------

    def _build_bm25_index(self):
        self.k1 = 1.5
        self.b = 0.75

        self.document_lengths = [
            len(document.tokens)
            for document in self.documents
        ]

        self.average_document_length = (
            sum(self.document_lengths)
            / len(self.document_lengths)
        )

        # Document frequency:
        # number of documents containing each term.
        self.document_frequency = {}

        for document in self.documents:
            unique_terms = set(document.tokens)

            for term in unique_terms:
                self.document_frequency[term] = (
                    self.document_frequency.get(term, 0) + 1
                )

    def _bm25_score(self, query_tokens: list[str], document: Document, document_index: int):
        term_counts = {}

        for token in document.tokens:
            term_counts[token] = term_counts.get(token, 0) + 1

        score = 0.0
        document_length = self.document_lengths[document_index]
        total_documents = len(self.documents)

        for term in query_tokens:
            if term not in term_counts:
                continue

            term_frequency = term_counts[term]
            document_frequency = self.document_frequency.get(term, 0)

            # BM25 inverse-document-frequency component.
            idf = math.log(
                1
                + (
                    total_documents
                    - document_frequency
                    + 0.5
                )
                / (
                    document_frequency + 0.5
                )
            )

            length_normalization = (
                1
                - self.b
                + self.b
                * document_length
                / self.average_document_length
            )

            term_score = idf * (
                term_frequency * (self.k1 + 1)
                / (
                    term_frequency
                    + self.k1 * length_normalization
                )
            )

            score += term_score

        return score

    def _search_bm25(self, query: str, top_k: int):
        query_tokens = tokenize(query)

        scored_documents = []

        for index, document in enumerate(self.documents):
            score = self._bm25_score(
                query_tokens,
                document,
                index,
            )

            if score > 0:
                scored_documents.append(
                    {
                        "document": document,
                        "score": score,
                    }
                )

        scored_documents.sort(
            key=lambda result: result["score"],
            reverse=True,
        )

        return scored_documents[:top_k]

    # ------------------------------------------------------------
    # Public search interface
    # ------------------------------------------------------------

    def search(
        self,
        query: str,
        method: str = "bm25",
        top_k: int = 5,
    ):
        method = method.lower()

        if method == "tfidf":
            return self._search_tfidf(query, top_k)

        if method == "bm25":
            return self._search_bm25(query, top_k)

        raise ValueError(
            "method must be either 'tfidf' or 'bm25'"
        )


def print_results(results):
    if not results:
        print("No matching documents found.")
        return

    for rank, result in enumerate(results, start=1):
        document = result["document"]
        score = result["score"]

        print(f"{rank}. {document.title}")
        print(f"   File: {document.path}")
        print(f"   Score: {score:.4f}")
        print()


if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        description="Search basketball recap markdown files."
    )
    parser.add_argument(
        "folder",
        nargs="?",
        default=str(RECAPS_FOLDER),
        help="Folder containing recap markdown files (defaults to the built-in recaps folder).",
    )
    args = parser.parse_args()

    engine = RecapSearchEngine(args.folder)

    print("Basketball recap keyword search")
    print("Use 'q', 'quit', or 'exit' to exit.\n")

    while True:
        query = input("Query: ").strip()

        if query.lower() in {"q", "quit", "exit"}:
            break

        if not query:
            continue

        method = input("Method [bm25/tfidf]: ").strip().lower()

        if method not in {"bm25", "tfidf"}:
            method = "bm25"

        results = engine.search(
            query=query,
            method=method,
            top_k=5,
        )

        print()
        print_results(results)
